"""Migration of Meridian CRM rule ACC-004 and its release audit event."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    """A blocking legacy business-rule validation failure."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: Any) -> Decimal:
    """Apply the legacy empty-string-to-zero numeric coercion."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account's credit hold under legacy rule ACC-004."""
    updated_account = account.copy()

    # Blank and every value other than 'Y' are treated as not on hold.
    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _numeric_value(account.get("CRED_LIMIT", "")) <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    account_id = account.get("ACCT_ID", "")
    entity_id = "" if account_id is None else str(account_id)

    return updated_account, [
        {"code": "CRED_HOLD_OFF", "entity_id": entity_id}
    ]
